@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Oswald:wght@400;500;600;700&display=swap');

:root {
  --bg: #111111;
  --bg-soft: #171717;
  --bg-elev: #1f1f1f;
  --text: #f5f5f5;
  --text-soft: #c8c8c8;
  --muted: #8c8c8c;
  --primary: #e63946;
  --primary-strong: #ff1f33;
  --border: #2a2a2a;
  --success: #34d399;
  --danger: #ff6b6b;
  --radius: 14px;
  --shadow: 0 18px 45px rgba(0, 0, 0, 0.35);
}

