html, body { margin: 0; padding: 0; }
body {
  font-family: 'Inter', Helvetica, Arial, sans-serif;
  background: radial-gradient(circle at top right, rgba(230,57,70,0.1), transparent 36%), var(--bg);
  color: var(--text);
  line-height: 1.6;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }

.topbar {
  background: #0c0c0c;
  border-bottom: 1px solid var(--border);
  color: var(--text-soft);
  font-size: .9rem;
}
.topbar-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: .65rem 1rem;
  display: flex;
  gap: 1rem;
  justify-content: space-between;
  align-items: center;
}
.topbar a { color: var(--primary); font-weight: 700; text-transform: uppercase; letter-spacing: .04em; }

header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(17, 17, 17, .92);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
}
.nav-wrap {
  max-width: 1200px;
  margin: 0 auto;
  padding: .8rem 1rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}
.brand {
  font-family: 'Oswald', sans-serif;
  font-size: 1.6rem;
  letter-spacing: .06em;
  text-transform: uppercase;
}
.brand span { color: var(--primary); }
.nav-links {
  display: flex;
  align-items: center;
  gap: 1.1rem;
  flex-wrap: wrap;
}
.nav-links a {
  font-size: .88rem;
  text-transform: uppercase;
  letter-spacing: .07em;
  color: var(--text-soft);
  transition: color .2s ease;
}
.nav-links a:hover,
.nav-links a.active { color: #fff; }

.container {
  width: min(1200px, 92vw);
  margin: 0 auto;
}
.section { padding: 4.5rem 0; }

.hero {
  min-height: 78vh;
  display: grid;
  place-items: center;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(0,0,0,.35), rgba(0,0,0,.8));
  z-index: 0;
}
.hero-bg {
  position: absolute;
  inset: 0;
  object-fit: cover;
  width: 100%;
  height: 100%;
}
.hero-content { position: relative; z-index: 1; max-width: 900px; padding: 0 1rem; }
.eyebrow {
  color: var(--primary);
  text-transform: uppercase;
  letter-spacing: .12em;
  font-size: .8rem;
  font-weight: 700;
}
h1, h2, h3 {
  font-family: 'Oswald', sans-serif;
  text-transform: uppercase;
  letter-spacing: .03em;
  line-height: 1.15;
  margin: 0 0 1rem;
}
h1 { font-size: clamp(2.2rem, 8vw, 5rem); }
h2 { font-size: clamp(1.6rem, 4vw, 2.6rem); }
h3 { font-size: clamp(1.2rem, 3vw, 1.7rem); }

.lead { font-size: 1.1rem; color: var(--text-soft); max-width: 780px; margin: 0 auto 1.7rem; }

.btn-row { display: flex; gap: .9rem; justify-content: center; flex-wrap: wrap; }
.btn {
  border: none;
  cursor: pointer;
  min-height: 46px;
  padding: .82rem 1.25rem;
  border-radius: 999px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .06em;
  font-size: .82rem;
  transition: transform .16s ease, background .2s ease, color .2s ease;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.btn:active { transform: scale(0.98); }
.btn-primary { background: var(--primary); color: #fff; }
.btn-primary:hover { background: var(--primary-strong); transform: translateY(-1px); }
.btn-ghost { background: transparent; border: 1px solid #ffffff50; color: #fff; }
.btn-ghost:hover { border-color: #fff; }

.grid-2 { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 1.2rem; }
.grid-3 { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 1.2rem; }
.card {
  background: linear-gradient(180deg, rgba(255,255,255,.03), rgba(255,255,255,.01));
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.4rem;
  box-shadow: var(--shadow);
}

.split {
  display: grid;
  grid-template-columns: 1.2fr .8fr;
  gap: 1.2rem;
  align-items: stretch;
}

.schedule-table {
  width: 100%;
  border-collapse: collapse;
  overflow: hidden;
  border-radius: var(--radius);
  border: 1px solid var(--border);
}
.schedule-table th,
.schedule-table td { padding: .9rem 1rem; text-align: left; }
.schedule-table th {
  background: #181818;
  font-family: 'Oswald', sans-serif;
  letter-spacing: .05em;
  text-transform: uppercase;
}
.schedule-table tr:nth-child(even) td { background: #141414; }
.schedule-table td { border-top: 1px solid var(--border); color: var(--text-soft); }

.carousel {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  height: clamp(280px, 52vw, 470px);
}
.carousel-track { display: flex; height: 100%; transition: transform .48s ease; }
.carousel-slide { min-width: 100%; position: relative; }
.carousel-slide img { width: 100%; height: 100%; object-fit: cover; }
.carousel-caption {
  position: absolute;
  left: 1rem;
  bottom: 1rem;
  background: rgba(0,0,0,.55);
  padding: .45rem .7rem;
  border-radius: .55rem;
  font-size: .85rem;
