.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 42px;
  height: 42px;
  border-radius: 50%;
  border: 1px solid #ffffff50;
  background: rgba(0,0,0,.42);
  color: #fff;
  font-size: 1.2rem;
  cursor: pointer;
}
.carousel-btn:hover { background: rgba(230,57,70,.8); border-color: transparent; }
.carousel-btn.prev { left: .7rem; }
.carousel-btn.next { right: .7rem; }

.filter-row { display: flex; gap: .8rem; align-items: center; flex-wrap: wrap; }
.select {
  background: #191919;
  color: #fff;
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: .68rem .85rem;
  min-width: 220px;
}

.faq-item { border-bottom: 1px solid var(--border); }
.faq-btn {
  width: 100%;
  text-align: left;
  background: transparent;
  border: none;
  color: #fff;
  font: inherit;
  padding: 1rem 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
}
.faq-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height .3s ease;
  color: var(--text-soft);
}
.faq-item.active .faq-content { max-height: 240px; padding-bottom: .85rem; }
.faq-symbol { color: var(--primary); font-size: 1.2rem; }

.newsletter {
  background: linear-gradient(135deg, rgba(230,57,70,.2), rgba(0,0,0,.2));
  border: 1px solid rgba(230,57,70,.3);
}
.newsletter-form { display: flex; gap: .7rem; flex-wrap: wrap; }
.input {
  flex: 1;
  min-width: 210px;
  background: #121212;
  color: #fff;
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: .78rem .9rem;
}
.input:focus { outline: 2px solid rgba(230,57,70,.5); border-color: var(--primary); }
.form-msg { margin-top: .65rem; font-size: .9rem; min-height: 1.2rem; }
.form-msg.error { color: var(--danger); }
.form-msg.success { color: var(--success); }

footer {
  margin-top: 2rem;
  border-top: 1px solid var(--border);
  background: #0f0f0f;
}
.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 1.6rem 1rem 2rem;
  display: grid;
  gap: 1.1rem;
}
.country-wrap { position: relative; display: inline-block; }
.country-menu {
  position: absolute;
  top: calc(100% + .5rem);
  left: 0;
  min-width: 210px;
  background: #191919;
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: .4rem;
  display: none;
  z-index: 12;
}
.country-menu.open { display: block; }
.country-item {
  width: 100%;
  background: transparent;
  color: var(--text-soft);
  border: none;
  text-align: left;
  border-radius: 8px;
  padding: .55rem .6rem;
  cursor: pointer;
}
.country-item:hover { background: #232323; color: #fff; }

@media (max-width: 960px) {
  .grid-3 { grid-template-columns: repeat(2, minmax(0,1fr)); }
  .split { grid-template-columns: 1fr; }
}
@media (max-width: 700px) {
  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .nav-wrap { flex-direction: column; align-items: flex-start; }
}
EOF

